if(page==='profile'){view.innerHTML=title('SUA IDENTIDADE NA ACADEMIA','Meu perfil','Mantenha seu cadastro e sua foto atualizados.')+`<div class="two-col"><section class="card"><div class="profile-hero">${avatar(S.me,true)}<div><h2>${esc(S.me.name)}</h2><span class="pill">${esc(S.me.ra)}</span> <span class="pill grey">${roles[S.me.role]}</span></div></div><form id="profileForm"><label>Nome completo<input name="name" required maxlength="120" value="${esc(S.me.name)}"></label><label>E-mail de contato<input name="email" type="email" required value="${esc(S.me.email)}"></label><label>Foto de perfil · JPG, PNG ou WebP<input id="profilePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="btn">Salvar meu perfil →</button></form></section><section class="card"><div class="eyebrow">ACESSO E SEGURANÇA</div><h2>Sua conta protegida.</h2><p class="small">E-mail de acesso: <strong>${esc(S.me.login_email)}</strong></p><p class="small">Você entra com sua conta ChatGPT. Para alterar a senha, use as configurações de segurança do provedor dessa conta.</p><p class="small">O RA é único e permanece associado ao seu histórico de aprendizagem e aos certificados.</p><a class="btn secondary" href="/signout-with-chatgpt?return_to=/aluno.html" target="_top">Sair e trocar conta</a></section></div>`;return}
